insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_136'
from (values
('127.887.d.1.A',3,'A student compares jobs as a licensed aircraft mechanic, an avionics tech and a shop owner who runs an independent repair station. She is:','["identifying and comparing employment opportunities, including entrepreneurship", "naming one job only", "avoiding work", "ignoring careers"]'::jsonb,0,'Career options.','original'),
('127.887.d.1.A',4,'Opening an independent repair station is an example of:','["a school club", "entrepreneurship in the aviation industry", "a hobby only", "unemployment"]'::jsonb,1,'Entrepreneurship.','original'),
('127.887.d.1.B',3,'On a hangar team, Kai covers a coworker''s inspection when the crew is short and shares notes at shift change. He is showing the ability to:','["hide information", "avoid teammates", "cooperate, contribute and collaborate as a member of a team", "work alone only"]'::jsonb,2,'Teamwork.','original'),
('127.887.d.1.B',4,'A strong team member in a maintenance crew:','["keeps secrets", "avoids tasks", "blames others", "shares information and helps the team reach its goal"]'::jsonb,3,'Collaboration.','original'),
('127.887.d.1.C',3,'A new mechanic learns that signing off work she didn''t do would break professional and legal standards. She is identifying:','["individual ethical and legal behavior standards according to professional and industry standards", "optional rules", "no rules", "only shop gossip"]'::jsonb,0,'Ethics.','original'),
('127.887.d.1.C',4,'Falsifying a maintenance record is:','["faster", "unethical and illegal", "acceptable", "encouraged"]'::jsonb,1,'Never falsify.','original'),
('127.887.d.1.D',3,'A trainee reads the Federal Aviation Regulations and learns that aviation communication relies on standard English phraseology. She is researching:','["only local rules", "only slang", "Federal Aviation Regulations and the impact of the English language on aviation", "no regulations"]'::jsonb,2,'FARs and English.','original'),
('127.887.d.1.D',4,'English is widely used as the common language of aviation because it:','["is easy", "is secret", "is local", "helps pilots and controllers from many countries communicate clearly"]'::jsonb,3,'Common language.','original'),
('127.887.d.1.E',3,'A safety class lists fatigue, stress and distraction as things that can cause errors in a hangar. They are identifying:','["human factors that may impact health and safety in a workplace", "no factors", "only weather", "only tools"]'::jsonb,0,'Human factors.','original'),
('127.887.d.1.E',4,'Working a double shift without rest raises the risk of mistakes because of:','["boredom of the tools", "fatigue", "lighting colors", "paint fumes only"]'::jsonb,1,'Fatigue risk.','original'),
('127.887.d.1.F',3,'A shop adds checklists and second-person inspections to catch mistakes caused by distraction. This shows:','["tool failure", "bad luck", "the role of human factors in maintaining health and safety in the workplace", "no role"]'::jsonb,2,'Reduce error.','original'),
('127.887.d.1.F',4,'A checklist helps a mechanic by:','["hiding errors", "slowing work", "adding steps", "reducing the chance of skipping a step"]'::jsonb,3,'Checklist value.','original'),
('127.887.d.1.G',3,'A technician who always follows the manual and speaks up about a loose bolt demonstrates how:','["an employee''s personal responsibility affects health and safety", "safety is someone else''s job", "rules don''t matter", "laziness helps"]'::jsonb,0,'Personal responsibility.','original'),
('127.887.d.1.G',4,'If a mechanic notices an unsafe condition but says nothing, the likely result is:','["extra safety", "a higher chance of injury or an aircraft problem", "nothing", "a bonus"]'::jsonb,1,'Speak up.','original'),
('127.887.d.1.H',3,'In a training scenario, a mechanic is pressured to skip a required inspection to meet a deadline. She chooses to refuse and report it. She is applying:','["skipping rules", "hiding problems", "reasoning skills to make ethical decisions in simulated workplace situations", "poor judgment"]'::jsonb,2,'Ethical choice.','original'),
('127.887.d.1.H',4,'When a supervisor asks for a shortcut that breaks a safety rule, the best response is to:','["do it faster", "hide it", "agree quietly", "politely refuse and follow the approved procedure"]'::jsonb,3,'Say no safely.','original'),
('127.887.d.1.I',3,'A hangar policy requires safety glasses, hearing protection, closed shoes and hair tied back. These are:','["industry standards for employee appearance and health habits", "optional items", "no rules", "style choices"]'::jsonb,0,'Appearance standards.','original'),
('127.887.d.1.I',4,'Loose jewelry is prohibited around aircraft engines because it can:','["look odd", "catch on moving parts or cause electrical shorts", "be heavy", "improve safety"]'::jsonb,1,'Jewelry hazard.','original'),
('127.887.d.1.J',3,'A new hire says ''please'' and ''thank you'' to the line crew and waits until a colleague finishes speaking. He is demonstrating:','["rude behavior", "ignoring others", "appropriate etiquette and behavior", "interrupting"]'::jsonb,2,'Etiquette.','original'),
('127.887.d.1.J',4,'Respectful workplace behavior includes:','["gossip", "ignoring people", "rudeness", "treating coworkers and customers courteously"]'::jsonb,3,'Courtesy.','original'),
('127.887.d.1.K',3,'A mechanic writes a clear squawk report and explains the problem to the pilot in plain language. She is demonstrating:','["effective written and oral communication skills", "no reports", "unclear notes", "mumbling"]'::jsonb,0,'Clear communication.','original'),
('127.887.d.1.K',4,'A clear written discrepancy report should include:','["nothing", "what the problem is, where it is and when it was found", "only a date", "only a name"]'::jsonb,1,'Report details.','original'),
('127.887.d.1.L',3,'While a pilot describes a noise she heard on landing, the technician pays attention, nods and asks follow-up questions. He is demonstrating:','["walking away", "ignoring", "effective listening skills", "interrupting"]'::jsonb,2,'Listening.','original'),
('127.887.d.1.L',4,'A good listener confirms understanding by:','["changing the subject", "guessing", "looking away", "summarizing what was said and asking clarifying questions"]'::jsonb,3,'Confirm.','original'),
('127.887.d.2.A',3,'A line mechanic explains the status of a repair to a pilot, then updates the work order in writing for the next shift. She is demonstrating:','["effective oral and written communication skills with individuals from various cultures and backgrounds", "avoiding communication", "only texting", "only speaking"]'::jsonb,0,'Communicate clearly.','original'),
('127.887.d.2.A',4,'Because aviation involves people from many countries, a technician should:','["speak fast", "use clear, simple language and confirm understanding", "skip confirmation", "use slang"]'::jsonb,1,'Cross-cultural clarity.','original'),
('127.887.d.2.B',3,'Before starting a brake replacement, a technician reads the work order to see exactly what repair the customer authorized. She is:','["ignoring the order", "guessing", "identifying the requirements of work orders and technical documents for repairs", "skipping documents"]'::jsonb,2,'Read the work order.','original'),
('127.887.d.2.B',4,'A work order is important because it:','["is optional", "lists jokes", "hides costs", "defines what work is to be done and authorized"]'::jsonb,3,'Work order role.','original'),
('127.887.d.2.C',3,'A mechanic reads a wiring schematic and an exploded parts drawing from the maintenance manual to replace a fuel pump. She is:','["locating and interpreting documents, including schematics, charts, graphs and drawings", "avoiding drawings", "using only memory", "guessing"]'::jsonb,0,'Interpret drawings.','original'),
('127.887.d.2.C',4,'An exploded parts drawing shows:','["a company logo", "how the pieces of an assembly fit together", "the price", "the pilot''s name"]'::jsonb,1,'Exploded view.','original'),
('127.887.d.2.D',3,'A student converts 2.5 inches to millimeters while checking a rivet spacing in the manual. She is demonstrating:','["no math", "only counting", "proficiency in metric and U.S. customary standard measurement systems", "only metric"]'::jsonb,2,'Convert units.','original'),
('127.887.d.2.D',4,'A 50.8 mm length is equal to how many inches?','["20 inches", "1 inch", "5 inches", "2 inches"]'::jsonb,3,'50.8 / 25.4 = 2.','original'),
('127.887.d.2.E',3,'A student reads a vernier caliper to check the diameter of a bolt to the thousandth of an inch. She is performing:','["precision measurements using engineering scales, dial calipers and vernier calipers", "eyeballing", "guessing", "a rough estimate"]'::jsonb,0,'Precision tools.','original'),
('127.887.d.2.E',4,'A dial caliper is used to measure:','["speed", "inside, outside and depth dimensions precisely", "weight", "temperature"]'::jsonb,1,'Caliper use.','original'),
('127.887.d.2.F',3,'After hearing a rough idle, a mechanic lists possible causes, tests each and finds a fouled plug. She is using:','["guessing", "luck", "critical-thinking and problem-solving skills to identify aircraft maintenance concerns", "random swapping"]'::jsonb,2,'Troubleshoot.','original'),
('127.887.d.2.F',4,'The most efficient first step in troubleshooting is to:','["guess", "ignore the report", "replace the engine", "gather information and check the simplest causes first"]'::jsonb,3,'Start simple.','original'),
('127.887.d.3.A',3,'A class reads about how people have watched birds and dreamed of flight for thousands of years. They are researching:','["the historical interest in flight", "only cars", "only boats", "no history"]'::jsonb,0,'Dream of flight.','original'),
('127.887.d.3.A',4,'Leonardo da Vinci''s sketches of flying machines show:','["modern jets", "early human interest in understanding flight", "space travel", "radio waves"]'::jsonb,1,'Early ideas.','original'),
('127.887.d.3.B',3,'A student compares a hot-air balloon with a glider and a powered airplane. She is describing:','["only trains", "only cars", "early aircraft designs such as lighter-than-air and heavier-than-air designs", "only ships"]'::jsonb,2,'Aircraft types.','original'),
('127.887.d.3.B',4,'A hot-air balloon is classified as a:','["glider", "rotorcraft", "heavier-than-air aircraft", "lighter-than-air aircraft"]'::jsonb,3,'Lighter than air.','original'),
('127.887.d.3.C',3,'A presentation highlights how Orville and Wilbur Wright tested wing shapes in a wind tunnel before their powered flight. This describes:','["contributions of pioneers in aviation history", "only cars", "no pioneers", "only ships"]'::jsonb,0,'Aviation pioneers.','original'),
('127.887.d.3.C',4,'The Wright brothers are credited with:','["the first rocket", "the first sustained, controlled, powered airplane flight", "the first balloon", "the first jet"]'::jsonb,1,'First flight.','original'),
('127.887.d.3.D',3,'A timeline shows that two world wars and the space race pushed fast improvements in engines and materials. This identifies:','["slow growth", "random events", "driving forces that provide rapid advancements in aircraft design and performance", "no change"]'::jsonb,2,'Drivers of advancement.','original'),
('127.887.d.3.D',4,'Military needs advanced aircraft design by:','["banning flight", "avoiding innovation", "stopping research", "funding faster, stronger and longer-range aircraft"]'::jsonb,3,'Military drive.','original'),
('127.887.d.3.E',3,'A student shows how air cargo, travel and weather satellites help communities and businesses. She is describing:','["the contributions of aviation and aerospace to society", "only games", "no benefits", "only costs"]'::jsonb,0,'Society benefits.','original'),
('127.887.d.3.E',4,'Air cargo benefits society mainly because it:','["avoids trade", "moves urgent and perishable goods quickly", "moves nothing", "is slow"]'::jsonb,1,'Air cargo.','original'),
('127.887.d.4.A',3,'A trainee locates maintenance and certification rules in Title 14 of the Code of Federal Regulations. She is:','["ignoring rules", "using only guesses", "identifying and locating aviation regulations prescribed by 14 Code of Federal Regulations", "reading a menu"]'::jsonb,2,'Find the CFR.','original'),
('127.887.d.4.A',4,'The aviation regulations that cover aircraft maintenance are found in:','["a school handbook", "Title 2", "Title 40", "Title 14 of the Code of Federal Regulations"]'::jsonb,3,'14 CFR.','original'),
('127.887.d.4.B',3,'A student explains how levers, lift and drag, and the stress on a wing spar relate to how aircraft are built and fly. She is applying:','["principles of simple machines, basic aerodynamics and aircraft structures", "only paint", "no principles", "only music"]'::jsonb,0,'Apply principles.','original'),
('127.887.d.4.B',4,'The four forces acting on an airplane in flight are:','["speed, color, sound, heat", "lift, weight, thrust and drag", "fuel, oil, air, water", "push, pull, spin, lift only"]'::jsonb,1,'Four forces.','original'),
('127.887.d.4.C',3,'A trainee sorts aircraft into airplanes, rotorcraft, gliders and lighter-than-air craft. She is:','["avoiding categories", "sorting ships", "identifying aircraft categories", "sorting cars"]'::jsonb,2,'Categories.','original'),
('127.887.d.4.C',4,'A helicopter is classified as a:','["airship", "balloon", "glider", "rotorcraft"]'::jsonb,3,'Rotorcraft.','original'),
('127.887.d.4.D',3,'A student learns what an airframe and powerplant mechanic certificate allows and the limits on what the holder may sign off. She is explaining:','["the certification process, ratings, privileges and limitations of airmen", "random rules", "no certificates", "unlimited privileges"]'::jsonb,0,'Certification.','original'),
('127.887.d.4.D',4,'An A&P certificate allows a holder to:','["fly any aircraft", "perform and approve maintenance within the rating''s privileges", "ignore rules", "build any aircraft"]'::jsonb,1,'A&P privileges.','original'),
('127.887.d.4.E',3,'A student compares wood, welded steel tube, aluminum sheet and composite airframes. She is identifying and comparing:','["house walls", "boat hulls", "airframe construction, including wood structures, metal tube and fabric, and metal and composite structures", "car frames"]'::jsonb,2,'Airframe types.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_136'
from (values
('127.887.d.4.E',4,'Modern airliners increasingly use composite materials because they are:','["heavy", "expensive only", "weak", "strong and lightweight"]'::jsonb,3,'Composite benefit.','original'),
('127.887.d.4.F',3,'A trainee describes how retractable landing gear, hydraulic lines and brakes work together on a plane. She is explaining:','["airframe systems and components, including landing gear and hydraulics", "seats", "paint", "engine only"]'::jsonb,0,'Airframe systems.','original'),
('127.887.d.4.F',4,'Hydraulic systems on aircraft are used to:','["play music", "operate landing gear, flaps and brakes with fluid pressure", "light cabins", "cook food"]'::jsonb,1,'Hydraulics.','original'),
('127.887.d.4.G',3,'A student explains how a piston engine''s four strokes differ from the way a turbine engine compresses, burns and exhausts air. She is describing:','["electric fans", "rocket fuel only", "aircraft reciprocating and turbine engine operating theory, functions and maintenance", "bicycle gears"]'::jsonb,2,'Engine theory.','original'),
('127.887.d.4.G',4,'The four strokes of a reciprocating engine are:','["push, pull, turn, hold", "start, run, stop, cool", "fuel, air, spark, oil", "intake, compression, power and exhaust"]'::jsonb,3,'Four-stroke.','original'),
('127.887.d.4.H',3,'A mechanic explains how oil temperature gauges, fuel systems and exhaust systems keep a powerplant running safely. She is identifying:','["powerplant systems and components, including engine instruments, fuel and lubrication", "cabin systems only", "airframe only", "seat belts only"]'::jsonb,0,'Powerplant systems.','original'),
('127.887.d.4.H',4,'An oil pressure gauge helps a pilot or mechanic know:','["airspeed", "whether the engine is being lubricated properly", "fuel remaining", "altitude"]'::jsonb,1,'Oil gauge.','original'),
('127.887.d.4.I',3,'A student learns that ''squawk'' means a reported discrepancy and ''torque stripe'' marks a verified fastener. She is explaining:','["no terms", "random slang", "common aircraft terminology and standard practices required to complete maintenance", "no practices"]'::jsonb,2,'Maintenance terms.','original'),
('127.887.d.4.I',4,'A torque stripe on a fastener is used to:','["hide damage", "decorate", "mark the owner", "show the fastener was torqued and has not moved"]'::jsonb,3,'Torque stripe.','original'),
('127.887.d.4.J',3,'A trainee reviews a sample entry that is missing the date, work done and signature and fixes it. She is:','["identifying necessary elements of logbook entries and critiquing sample entries", "guessing", "skipping records", "ignoring logs"]'::jsonb,0,'Logbook elements.','original'),
('127.887.d.4.J',4,'A complete maintenance logbook entry includes:','["only a signature", "the date, a description of work, and the signature and certificate number of the person", "a joke", "only a date"]'::jsonb,1,'Complete entry.','original'),
('127.887.d.4.K',3,'A student describes the annual inspection and 100-hour inspection required to keep an aircraft airworthy. She is describing:','["no inspections", "only paint checks", "inspections required to maintain compliance with airworthiness and safety requirements", "optional checks"]'::jsonb,2,'Required inspections.','original'),
('127.887.d.4.K',4,'An annual inspection is required to:','["check the radio", "clean the cabin", "paint the plane", "verify an aircraft remains airworthy once every 12 calendar months"]'::jsonb,3,'Annual inspection.','original'),
('127.887.d.5.A',3,'A student practices using a torque wrench, safety wire pliers and a drill press while following shop rules. She is demonstrating:','["basic skills in safely using hand tools, power tools and equipment", "unsafe tool use", "skipping rules", "using no tools"]'::jsonb,0,'Tool skills.','original'),
('127.887.d.5.A',4,'Before using a power tool in the shop, a student should:','["skip inspection", "inspect it and put on required eye protection", "remove guards", "ignore safety"]'::jsonb,1,'Tool prep.','original'),
('127.887.d.5.B',3,'A shop collects used oil, solvents and hydraulic fluid in labeled drums for a licensed disposal company. This shows:','["dumping waste", "burning waste", "the proper handling and disposal of environmentally hazardous materials", "hiding waste"]'::jsonb,2,'Hazmat disposal.','original'),
('127.887.d.5.B',4,'A Safety Data Sheet tells a technician:','["the price", "the color", "the weather", "how to handle a chemical safely and what to do in an emergency"]'::jsonb,3,'SDS purpose.','original'),
('127.887.d.5.C',3,'A report describes electric propulsion, drones and composite airframes as changes in the industry. She is describing:','["the impact of new and emerging aircraft technologies", "no change", "only history", "old equipment"]'::jsonb,0,'Emerging tech.','original'),
('127.887.d.5.C',4,'A potential benefit of electric aircraft is:','["no benefit", "lower emissions and quieter operation", "higher emissions", "more noise"]'::jsonb,1,'Electric benefits.','original'),
('127.887.d.5.D',3,'A shop plans scheduled lubrication, filter changes and inspections so that parts are replaced before they fail. She is examining:','["waiting for breakdown", "random repairs", "the need for preventative maintenance procedures and practices", "no plan"]'::jsonb,2,'Preventive maintenance.','original'),
('127.887.d.5.D',4,'Preventative maintenance in aviation is important mainly because it:','["adds risk", "causes failures", "wastes time", "finds problems before they cause failures in flight"]'::jsonb,3,'Prevent failure.','original'),
('127.887.d.6.A',3,'Using a flight simulator, a student follows a checklist to start the engine and perform a ground run-up. She is:','["starting and ground operating an aircraft or simulated aircraft using a high-fidelity simulator", "skipping the checklist", "guessing", "flying a kite"]'::jsonb,0,'Ground operation.','original'),
('127.887.d.6.A',4,'A checklist is used when starting an aircraft engine so that:','["speed is lost", "no required step is missed", "safety is reduced", "steps are skipped"]'::jsonb,1,'Use checklists.','original'),
('127.887.d.6.B',3,'To replace a hydraulic filter, a student finds the correct procedure in the maintenance manual and writes down the steps. She is:','["using no sources", "guessing", "researching and locating appropriate documentation to perform a function in a written report", "skipping the manual"]'::jsonb,2,'Find documentation.','original'),
('127.887.d.6.B',4,'Maintenance procedures should come from:','["a random website", "a rumor", "a friend''s memory", "the manufacturer''s approved maintenance manual"]'::jsonb,3,'Approved data.','original'),
('127.887.d.6.C',3,'A student sketches the top, side and front views of a small airplane to show its shape and dimensions. She is drawing:','["top, side and front views of aircraft categories", "a menu", "a map", "a cartoon"]'::jsonb,0,'Three views.','original'),
('127.887.d.6.C',4,'A three-view drawing is useful because it:','["hides details", "shows an object''s shape from several angles", "is decorative only", "shows only the color"]'::jsonb,1,'Orthographic views.','original'),
('127.887.d.6.D',3,'Using a checklist, a student inspects the tires, control surfaces and engine mounts of a trainer aircraft. She is performing:','["a paint job", "random checks", "basic airframe and engine inspections according to a checklist", "no inspections"]'::jsonb,2,'Basic inspection.','original'),
('127.887.d.6.D',4,'If a student finds a cracked fitting during an inspection, she should:','["fly anyway", "paint over it", "ignore it", "report it and not release the aircraft until it is evaluated"]'::jsonb,3,'Report defects.','original'),
('127.887.d.6.E',3,'A student uses a chart that links a symptom such as rough running to possible causes like a fouled spark plug or low fuel pressure. She is using:','["an engine troubleshooting chart to show the results of simple defects on engine operation", "guessing", "a menu", "a map"]'::jsonb,0,'Troubleshooting chart.','original'),
('127.887.d.6.E',4,'A troubleshooting chart helps a mechanic:','["hide the problem", "narrow down likely causes from a symptom", "avoid the manual", "skip testing"]'::jsonb,1,'Use charts.','original'),
('127.887.d.6.F',3,'A student outlines a plan that schedules oil changes and inspections by flight hours so that an aircraft stays in good working order. She is discussing:','["random service", "no plans", "preventative maintenance plans and systems to keep aircraft in airworthy condition", "waiting for failure"]'::jsonb,2,'Maintenance plans.','original'),
('127.887.d.6.F',4,'Scheduling maintenance by flight hours lets an operator:','["wait for problems", "avoid checks", "ignore wear", "service the aircraft before wear leads to a failure"]'::jsonb,3,'Interval scheduling.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
